window.PAGES["day2-lab"] = {"title": "Day 2 Lab \u2014 Security & Governance | 1Z0-1067-26", "css": "\n:host{\n  --bg:#0d1117; --bg2:#11161d; --panel:#151b23; --panel2:#1a212b;\n  --border:#232b36; --border-soft:#1d2530;\n  --text:#e6ebf1; --text-dim:#9aa7b6; --text-faint:#5f6b7a;\n  --red:#ff3b30; --red-dim:#c62b22; --red-glow:rgba(255,59,48,.25);\n  --blue:#4da3ff; --blue-dim:#2f6fd1;\n  --orange:#ffab40; --green:#3ddc84; --green-dim:#279a5c;\n  --yellow:#ffd54a; --purple:#b48bff;\n  --radius:14px; --radius-sm:9px;\n  --shadow: 0 8px 30px rgba(0,0,0,.35);\n  --mono: 'SFMono-Regular', Consolas, 'Courier New', monospace;\n  --sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Inter, Roboto, Helvetica, Arial, sans-serif;\n}\n[data-theme=\"light\"]{\n  --bg:#f4f5f7; --bg2:#eceef1; --panel:#ffffff; --panel2:#f7f8fa;\n  --border:#e1e4e9; --border-soft:#ebedf0;\n  --text:#1b2129; --text-dim:#5b6572; --text-faint:#8b95a3;\n  --red:#e0342a; --red-dim:#c62b22; --red-glow:rgba(224,52,42,.18);\n  --shadow: 0 8px 30px rgba(20,20,30,.08);\n}\n*{box-sizing:border-box; margin:0; padding:0;}\n:host{scroll-behavior:smooth;}\n:host{background:var(--bg); color:var(--text); font-family:var(--sans); min-height:100%; overflow-x:hidden; transition:background .3s,color .3s;}\nbody::before{content:''; position:fixed; inset:0; pointer-events:none; z-index:0;\n  background: radial-gradient(circle at 15% 10%, var(--red-glow), transparent 40%), radial-gradient(circle at 85% 90%, rgba(77,163,255,.10), transparent 45%);}\n::-webkit-scrollbar{width:10px; height:10px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border); border-radius:10px;}\na{color:inherit;} button{font-family:inherit; cursor:pointer;}\n\n.topbar{position:sticky; top:0; z-index:100; display:flex; align-items:center; gap:14px; padding:10px 18px;\n  background:color-mix(in srgb, var(--panel) 88%, transparent); backdrop-filter:blur(14px); border-bottom:1px solid var(--border-soft);}\n.brand{display:flex; align-items:center; gap:10px; font-weight:700;}\n.brand .logo{width:30px; height:30px; border-radius:8px; background:linear-gradient(135deg, var(--red), var(--red-dim));\n  display:flex; align-items:center; justify-content:center; font-size:13px; color:#fff; font-weight:800; box-shadow:0 4px 14px var(--red-glow);}\n.brand small{display:block; font-weight:500; color:var(--text-faint); font-size:10.5px; letter-spacing:.5px;}\n.crumb{display:flex; align-items:center; gap:6px; font-size:12.5px; color:var(--text-dim); flex:1; min-width:0; overflow:hidden; white-space:nowrap;}\n.crumb b{color:var(--text); font-weight:600;}\n.topbar-right{display:flex; align-items:center; gap:10px;}\n.xp-chip{display:flex; align-items:center; gap:7px; background:var(--panel2); border:1px solid var(--border); padding:6px 12px; border-radius:20px; font-size:12.5px; font-weight:600;}\n.xp-chip .dot{width:7px; height:7px; border-radius:50%; background:var(--orange); box-shadow:0 0 8px var(--orange);}\n.rank-chip{background:linear-gradient(135deg, var(--red), var(--red-dim)); color:#fff; font-size:11.5px; font-weight:700; padding:6px 11px; border-radius:20px;}\n.icon-btn{width:34px; height:34px; border-radius:9px; border:1px solid var(--border); background:var(--panel2); color:var(--text-dim); display:flex; align-items:center; justify-content:center; font-size:15px; transition:.15s;}\n.icon-btn:hover{color:var(--text); border-color:var(--text-faint);}\n\n.app{display:flex; min-height:calc(100% - 54px); position:relative; z-index:1;}\n.sidebar{width:255px; flex-shrink:0; border-right:1px solid var(--border-soft); padding:16px 10px; position:sticky; top:54px; height:calc(100% - 54px); overflow-y:auto; background:color-mix(in srgb, var(--bg2) 60%, transparent);}\n.sidebar h4{font-size:10.5px; text-transform:uppercase; letter-spacing:1px; color:var(--text-faint); padding:14px 10px 6px;}\n.nav-item{display:flex; align-items:center; gap:10px; padding:9px 10px; border-radius:9px; font-size:12.5px; color:var(--text-dim); cursor:pointer; transition:.15s; margin-bottom:2px; border:1px solid transparent;}\n.nav-item .n-ico{width:22px; text-align:center; font-size:12.5px; flex-shrink:0;}\n.nav-item:hover{background:var(--panel2); color:var(--text);}\n.nav-item.active{background:var(--red-glow); color:var(--text); border-color:var(--red-dim); font-weight:600;}\n.nav-item.locked{opacity:.4; cursor:not-allowed;}\n.nav-item.done .n-ico{color:var(--green);}\n.nav-badge{margin-left:auto; font-size:10px; background:var(--panel); border:1px solid var(--border); padding:1px 6px; border-radius:8px; color:var(--text-faint);}\n.nav-item.done .nav-badge{color:var(--green); border-color:var(--green-dim);}\n.progress-mini{margin:10px 8px 4px; padding:10px; background:var(--panel); border:1px solid var(--border); border-radius:10px;}\n.progress-mini .lbl{display:flex; justify-content:space-between; font-size:11px; color:var(--text-dim); margin-bottom:6px;}\n.bar-track{height:6px; border-radius:5px; background:var(--border-soft); overflow:hidden;}\n.bar-fill{height:100%; background:linear-gradient(90deg, var(--red), var(--orange)); border-radius:5px; transition:width .5s ease;}\n\n.main{flex:1; min-width:0; padding:26px 30px 80px;}\n.view{display:none; animation:fadeIn .35s ease;}\n.view.active{display:block;}\n@keyframes fadeIn{from{opacity:0; transform:translateY(8px);} to{opacity:1; transform:translateY(0);}}\n.section-head{margin-bottom:22px;}\n.eyebrow{font-size:11px; text-transform:uppercase; letter-spacing:1.5px; color:var(--red); font-weight:700; margin-bottom:6px;}\nh1.page-title{font-size:25px; font-weight:800; letter-spacing:-.3px;}\n.page-sub{color:var(--text-dim); font-size:13.5px; margin-top:5px; max-width:700px;}\n.card{background:var(--panel); border:1px solid var(--border); border-radius:var(--radius); padding:20px; box-shadow:var(--shadow);}\n.grid{display:grid; gap:16px;}\n.grid-2{grid-template-columns:1fr 1fr;} .grid-3{grid-template-columns:repeat(3,1fr);} .grid-4{grid-template-columns:repeat(4,1fr);} .grid-6{grid-template-columns:repeat(6,1fr);}\n@media(max-width:1000px){.grid-2,.grid-3,.grid-4,.grid-6{grid-template-columns:1fr 1fr;}}\n@media(max-width:650px){.grid-2,.grid-3,.grid-4,.grid-6{grid-template-columns:1fr;}}\n.btn{display:inline-flex; align-items:center; gap:8px; padding:11px 20px; border-radius:10px; border:none; font-weight:700; font-size:13.5px; transition:.15s;}\n.btn-primary{background:linear-gradient(135deg,var(--red),var(--red-dim)); color:#fff; box-shadow:0 6px 20px var(--red-glow);}\n.btn-primary:hover{transform:translateY(-1px); box-shadow:0 10px 26px var(--red-glow);}\n.btn-ghost{background:var(--panel2); color:var(--text); border:1px solid var(--border);}\n.btn-ghost:hover{border-color:var(--text-faint);}\n.btn-sm{padding:7px 13px; font-size:12px; border-radius:8px;}\n.btn:disabled{opacity:.4; cursor:not-allowed; transform:none !important;}\n.pill{display:inline-flex; align-items:center; gap:5px; font-size:11px; font-weight:700; padding:3px 9px; border-radius:20px;}\n.pill-green{background:rgba(61,220,132,.14); color:var(--green);}\n.pill-red{background:rgba(255,59,48,.14); color:var(--red);}\n.pill-orange{background:rgba(255,171,64,.14); color:var(--orange);}\n.pill-blue{background:rgba(77,163,255,.14); color:var(--blue);}\n.pill-purple{background:rgba(180,139,255,.14); color:var(--purple);}\n.pill-gray{background:var(--panel2); color:var(--text-faint); border:1px solid var(--border);}\n#toast-wrap{position:fixed; bottom:22px; right:22px; z-index:9999; display:flex; flex-direction:column; gap:10px;}\n.toast{background:var(--panel); border:1px solid var(--border); border-radius:12px; padding:13px 16px; box-shadow:var(--shadow); display:flex; align-items:center; gap:10px; min-width:260px; animation:toastIn .3s ease; font-size:13px;}\n@keyframes toastIn{from{opacity:0; transform:translateX(30px);} to{opacity:1; transform:translateX(0);}}\n.toast .t-ico{font-size:18px;} .toast b{display:block; font-size:12.5px;} .toast span{color:var(--text-dim); font-size:11.5px;}\n.toast.xp b{color:var(--orange);} .toast.ok .t-ico{color:var(--green);} .toast.err .t-ico{color:var(--red);}\n\n.mission-map{position:relative; padding:20px 10px;}\n.mission-track{display:flex; flex-wrap:wrap; gap:18px;}\n.m-node{width:205px; background:var(--panel); border:1px solid var(--border); border-radius:16px; padding:16px; position:relative; transition:.2s; cursor:pointer;}\n.m-node:hover{transform:translateY(-3px); border-color:var(--text-faint);}\n.m-node.locked{opacity:.45; cursor:not-allowed; filter:grayscale(.6);}\n.m-node.locked:hover{transform:none;}\n.m-node.done{border-color:var(--green-dim); background:linear-gradient(180deg, rgba(61,220,132,.06), var(--panel));}\n.m-node.current{border-color:var(--red-dim); box-shadow:0 0 0 3px var(--red-glow);}\n.m-num{width:32px; height:32px; border-radius:10px; background:var(--panel2); border:1px solid var(--border); display:flex; align-items:center; justify-content:center; font-weight:800; font-size:12px; margin-bottom:8px;}\n.m-node.done .m-num{background:var(--green); color:#052e17; border-color:var(--green);}\n.m-node.current .m-num{background:var(--red); color:#fff; border-color:var(--red);}\n.m-node h4{font-size:13.5px; margin-bottom:4px;}\n.m-node p{font-size:11px; color:var(--text-dim); line-height:1.5; margin-bottom:8px;}\n.m-node .m-xp{font-size:10.5px; color:var(--orange); font-weight:700;}\n\n.field{margin-bottom:14px;}\n.field label{display:block; font-size:12px; color:var(--text-dim); margin-bottom:6px; font-weight:600;}\n.field input, .field select, .field textarea{width:100%; padding:10px 12px; border-radius:9px; border:1px solid var(--border); background:var(--panel2); color:var(--text); font-size:13px; font-family:inherit;}\n.field input:focus, .field select:focus, .field textarea:focus{outline:none; border-color:var(--red-dim);}\n\n.hr{height:1px; background:var(--border-soft); margin:20px 0;}\n.two-col{display:grid; grid-template-columns:1fr 1fr; gap:18px;}\n@media(max-width:900px){.two-col{grid-template-columns:1fr;} .sidebar{display:none;}}\n.tag-list{display:flex; flex-wrap:wrap; gap:8px;}\n.info-box{padding:12px 14px; border-radius:10px; border-left:3px solid var(--blue-dim); background:rgba(77,163,255,.06); font-size:12.5px; margin:12px 0;}\n.tip-box{padding:12px 14px; border-radius:10px; border-left:3px solid var(--orange); background:rgba(255,171,64,.07); font-size:12.5px; margin:12px 0;}\n.mistake-box{padding:12px 14px; border-radius:10px; border-left:3px solid var(--red); background:rgba(255,59,48,.06); font-size:12.5px; margin:12px 0;}\n.hidden{display:none !important;}\n.chip-row{display:flex; flex-wrap:wrap; gap:8px; margin-bottom:12px;}\n.chip{padding:8px 13px; background:var(--panel2); border:1px solid var(--border); border-radius:8px; font-size:12px; font-weight:600; cursor:pointer; transition:.15s;}\n.chip:hover{border-color:var(--text-faint);}\n.chip.active{background:var(--red-glow); border-color:var(--red-dim);}\n\n.quiz-q{margin-bottom:20px; padding-bottom:16px; border-bottom:1px solid var(--border-soft);}\n.quiz-q:last-child{border:none;}\n.quiz-q .q-txt{font-weight:700; font-size:14px; margin-bottom:12px;}\n.q-opt{display:flex; align-items:center; gap:10px; padding:11px 14px; border:1px solid var(--border); border-radius:10px; margin-bottom:8px; cursor:pointer; transition:.15s; font-size:13px;}\n.q-opt:hover{border-color:var(--text-faint);}\n.q-opt.correct{border-color:var(--green-dim); background:rgba(61,220,132,.1);}\n.q-opt.incorrect{border-color:var(--red-dim); background:rgba(255,59,48,.1);}\n.q-explain{margin-top:8px; padding:10px 12px; background:var(--panel2); border-radius:9px; font-size:12px; color:var(--text-dim); display:none; border-left:3px solid var(--blue-dim);}\n.q-explain.show{display:block;}\n\n.ach-card{text-align:center; padding:20px 12px; border-radius:14px; border:1px solid var(--border); background:var(--panel); transition:.2s;}\n.ach-card.locked{opacity:.35; filter:grayscale(1);}\n.ach-card .ico{font-size:32px; margin-bottom:8px;}\n.ach-card h5{font-size:12.5px; margin-bottom:4px;}\n.ach-card p{font-size:10.5px; color:var(--text-dim);}\n\n.health-meter{margin-bottom:12px;}\n.health-meter .hm-lbl{display:flex; justify-content:space-between; font-size:11.5px; color:var(--text-dim); margin-bottom:5px;}\n.hm-track{height:8px; border-radius:6px; background:var(--border-soft); overflow:hidden;}\n.hm-fill{height:100%; border-radius:6px; transition:width .5s ease;}\n\n.threat-card{border:1px solid var(--border); border-radius:12px; padding:14px; background:var(--panel2); margin-bottom:10px;}\n.threat-card.high{border-color:var(--red-dim);}\n.threat-card.medium{border-color:var(--orange);}\n.threat-card.low{border-color:var(--blue-dim);}\n\n.hier-tree{display:flex; flex-direction:column; gap:8px; padding-left:0;}\n.hier-node{padding:10px 14px; border-radius:9px; border:1px solid var(--border); background:var(--panel2); cursor:pointer; transition:.15s; font-size:13px; font-weight:600;}\n.hier-node.child{margin-left:26px;}\n.hier-node.selected{border-color:var(--red-dim); background:var(--red-glow);}\n.hier-node.covered{border-color:var(--green-dim);}\n.hier-node.exposed{border-color:var(--red-dim); background:rgba(255,59,48,.08);}\n\n.detector-row{display:flex; align-items:center; gap:12px; padding:12px 14px; border:1px solid var(--border); border-radius:10px; margin-bottom:8px; background:var(--panel2);}\n.toggle{width:40px; height:22px; border-radius:20px; background:var(--border); position:relative; cursor:pointer; flex-shrink:0; transition:.2s;}\n.toggle.on{background:var(--green-dim);}\n.toggle .knob{width:18px; height:18px; border-radius:50%; background:#fff; position:absolute; top:2px; left:2px; transition:.2s;}\n.toggle.on .knob{left:20px;}\n\n.finding-row{display:flex; align-items:center; gap:10px; padding:10px 12px; border:1px solid var(--border); border-radius:9px; margin-bottom:6px; background:var(--panel2); font-size:12.5px;}\n.sev-badge{font-size:10px; font-weight:800; padding:2px 8px; border-radius:6px; text-transform:uppercase;}\n.sev-badge.critical{background:rgba(255,59,48,.2); color:var(--red);}\n.sev-badge.high{background:rgba(255,59,48,.14); color:var(--red);}\n.sev-badge.medium{background:rgba(255,171,64,.18); color:var(--orange);}\n.sev-badge.low{background:rgba(77,163,255,.18); color:var(--blue);}\n\n.gauge-wrap{text-align:center;}\n.gauge-track{height:8px; border-radius:6px; background:var(--border-soft); overflow:hidden; margin:8px 0;}\n.gauge-fill{height:100%; border-radius:6px; transition:width .6s ease;}\n\n.slider-wrap{margin:16px 0;}\n.slider-wrap input[type=range]{width:100%;}\n\n.state-json{background:#0a0d12; border:1px solid #232b36; border-radius:10px; padding:14px; font-family:var(--mono); font-size:11.5px; color:#c9d2dc; max-height:320px; overflow:auto; white-space:pre;}\n\n", "html": "\n<div id=\"toast-wrap\"></div>\n<div class=\"topbar\">\n  <div class=\"brand\"><div class=\"logo\">C</div><div>Day 2 Lab <small>1Z0-1067-26 \u00b7 Security &amp; Governance</small></div></div>\n  <div class=\"crumb\">Home <span>\u203a</span> <b id=\"crumbCurrent\">Mission Control</b></div>\n  <div class=\"topbar-right\">\n    <div class=\"xp-chip\"><span class=\"dot\"></span><span id=\"xpDisplay\">0</span> XP</div>\n    <div class=\"rank-chip\" id=\"rankChip\">New Hire</div>\n    <button class=\"icon-btn\" id=\"themeToggle\" title=\"Toggle theme\">\u25d0</button>\n  </div>\n</div>\n<div class=\"app\">\n  <div class=\"sidebar\" id=\"sidebar\"></div>\n  <div class=\"main\" id=\"main\"></div>\n</div>\n\n", "js": "\n/* ================= DATA ================= */\nconst NAV = [\n  {id:'home', label:'SOC Dashboard', ico:'\u2302', group:'main'},\n  {id:'missionmap', label:'Mission Map', ico:'\ud83d\uddfa', group:'main'},\n  {id:'m1', label:'M1 \u00b7 Enable Cloud Guard', ico:'\u2460', group:'missions'},\n  {id:'m2', label:'M2 \u00b7 Cloud Guard Target', ico:'\u2461', group:'missions'},\n  {id:'m3', label:'M3 \u00b7 Detector Recipes', ico:'\u2462', group:'missions'},\n  {id:'m4', label:'M4 \u00b7 Responder Recipes', ico:'\u2463', group:'missions'},\n  {id:'m5', label:'M5 \u00b7 Security Zones', ico:'\u2464', group:'missions'},\n  {id:'m6', label:'M6 \u00b7 Budgets', ico:'\u2465', group:'missions'},\n  {id:'m7', label:'M7 \u00b7 Cost Analysis', ico:'\u2466', group:'missions'},\n  {id:'troubleshoot', label:'Troubleshooting', ico:'\ud83e\udde9', group:'extra'},\n  {id:'exam', label:'Exam Challenges', ico:'\ud83d\udcdd', group:'extra'},\n  {id:'achievements', label:'Achievements', ico:'\ud83c\udfc6', group:'extra'},\n  {id:'capstone', label:'Capstone Lab', ico:'\ud83c\udf93', group:'extra'},\n];\n\nconst MISSIONS = [\n  {id:'m1', num:1, title:'Enable Cloud Guard', desc:'Turn on tenancy-wide threat detection.', xp:100},\n  {id:'m2', num:2, title:'Create Cloud Guard Target', desc:'Choose what Cloud Guard actually watches.', xp:90},\n  {id:'m3', num:3, title:'Configure Detector Recipes', desc:'Tune the rules that spot risky resources.', xp:110},\n  {id:'m4', num:4, title:'Configure Responder Recipes', desc:'Automate remediation for common threats.', xp:120},\n  {id:'m5', num:5, title:'Deploy Security Zone', desc:'Make insecure deployments impossible.', xp:120},\n  {id:'m6', num:6, title:'Create Budgets', desc:'Set spending limits and alert thresholds.', xp:90},\n  {id:'m7', num:7, title:'Analyze Costs', desc:'Find and eliminate wasted cloud spend.', xp:110},\n];\nconst MISSION_ORDER = MISSIONS.map(m=>m.id);\n\nconst INSECURE_FINDINGS = [\n  {label:'Open Security List (0.0.0.0/0 : 22)', sev:'critical'},\n  {label:'Public Object Storage Bucket \"app-backups\"', sev:'high'},\n  {label:'No tenancy-wide threat monitoring', sev:'high'},\n  {label:'IAM user with no MFA and unused API key', sev:'medium'},\n];\nconst CLOUD_GUARD_CONCEPTS = [\n  {term:'Cloud Guard', def:'OCI\\'s native security posture and threat detection service \u2014 continuously monitors resources for misconfigurations and suspicious activity.'},\n  {term:'Detector Recipe', def:'A set of rules Cloud Guard uses to identify risky configurations (e.g. a public bucket).'},\n  {term:'Responder Recipe', def:'A set of automated or manual actions Cloud Guard can take when a problem is detected.'},\n  {term:'Target', def:'The compartment (or root tenancy) that a Detector/Responder Recipe pair actually applies to.'},\n];\nconst ATTACK_ALERTS = [\n  {sev:'high', title:'Port scan detected from 203.0.113.9', desc:'An external IP swept common ports (22, 3389, 3306) against a public subnet.'},\n  {sev:'medium', title:'Unusual API call volume', desc:'A service account made 40x its normal number of ListBucket calls in 5 minutes.'},\n  {sev:'low', title:'New IAM user created outside business hours', desc:'A user account was created at 2:14 AM local time \u2014 worth a review, not necessarily malicious.'},\n];\n\nconst HIERARCHY = [\n  {id:'root', label:'Root Tenancy', level:0},\n  {id:'dev', label:'Development', level:1},\n  {id:'test', label:'Testing', level:1},\n  {id:'prod', label:'Production', level:1},\n];\n\nconst DETECTORS = [\n  {id:'pubstorage', label:'Public Object Storage', risk:'A bucket readable by anyone on the internet can leak sensitive data.', severity:'High',\n    example:'A misconfigured backups bucket exposed customer invoices for 11 days before detection.',\n    examtip:'Cloud Guard\\'s Object Storage detector flags \"Public Access Enabled\" \u2014 know this is the primary control at exam time.',\n    mistake:'Teams often set a bucket public \"temporarily\" for a demo and forget to revert it.'},\n  {id:'pubcompute', label:'Public Compute', risk:'Instances with a public IP and permissive security rules are directly reachable by attackers.', severity:'High',\n    example:'A dev VM left with a public IP and open RDP port was compromised and used for crypto-mining.',\n    examtip:'Prefer a bastion/Load Balancer over assigning public IPs directly to instances.',\n    mistake:'Assigning a public IP \"just in case\" during testing, then shipping it to production unchanged.'},\n  {id:'openseclist', label:'Open Security Lists', risk:'A security list open to 0.0.0.0/0 on sensitive ports invites brute-force and scanning traffic.', severity:'Critical',\n    example:'SSH (port 22) open to the internet led to thousands of automated login attempts within hours.',\n    examtip:'Cloud Guard treats 0.0.0.0/0 ingress on management ports (22/3389) as a top-severity finding.',\n    mistake:'Copy-pasting a security list from a tutorial without narrowing the source CIDR.'},\n  {id:'weakiam', label:'Weak IAM Policy', risk:'Overly broad policies (e.g. \"manage all-resources in tenancy\" for a normal user) violate least privilege.', severity:'Medium',\n    example:'A contractor account had tenancy-admin rights months after the contract ended.',\n    examtip:'Detector checks for policies granting broad \"manage\" verbs at the tenancy level to non-admin groups.',\n    mistake:'Granting Administrators-level access \"temporarily\" to unblock someone, then never revoking it.'},\n  {id:'dbexposure', label:'Database Exposure', risk:'A database accessible from the public internet bypasses your application\\'s access controls entirely.', severity:'Critical',\n    example:'An Autonomous Database left with a public endpoint was targeted by credential-stuffing bots.',\n    examtip:'Databases should sit in private subnets, reached only via application tiers or a bastion.',\n    mistake:'Enabling a public endpoint for \"easy access during development\" and never disabling it.'},\n];\nconst SCAN_FINDINGS = [\n  {label:'Public Bucket Found', sev:'high'},\n  {label:'Security List Open to Internet', sev:'critical'},\n  {label:'Unencrypted Volume', sev:'medium'},\n  {label:'Unused IAM User', sev:'low'},\n];\n\nconst RESPONDER_THREATS = [\n  {id:'pubbucket', label:'Public Bucket', correctAction:'makeprivate'},\n  {id:'openport', label:'Open Port', correctAction:'closeport'},\n  {id:'unuseduser', label:'Unused User', correctAction:'disableuser'},\n  {id:'unencrypted', label:'Unencrypted Volume', correctAction:'alert'},\n];\nconst RESPONDER_ACTIONS = [\n  {id:'makeprivate', label:'Automatically Make Private'},\n  {id:'closeport', label:'Close Port'},\n  {id:'disableuser', label:'Disable User'},\n  {id:'alert', label:'Create Alert'},\n];\n\nconst SECURITY_ZONE_RULES = [\n  'No Public Buckets', 'Mandatory Encryption', 'No Public IPs', 'No Internet Gateway', 'No Weak IAM Policies',\n];\nconst BLOCKED_ATTEMPTS = [\n  {id:'pubbucket', label:'Create Public Bucket', reason:'Security Zone policy \"No Public Buckets\" blocks any bucket created with public visibility.'},\n  {id:'pubcompute', label:'Create Public Compute', reason:'Security Zone policy \"No Public IPs\" prevents attaching a public IP to any instance in this zone.'},\n  {id:'pubdb', label:'Create Public Database', reason:'Security Zone policy \"No Public IPs\" also blocks public database endpoints.'},\n  {id:'weakenc', label:'Deploy with Weak Encryption', reason:'Security Zone policy \"Mandatory Encryption\" requires customer-managed or Oracle-managed encryption on all storage.'},\n  {id:'igw', label:'Attach Internet Gateway', reason:'Security Zone policy \"No Internet Gateway\" keeps this compartment fully private \u2014 no direct internet route allowed.'},\n];\nconst COMPLIANCE_AREAS = [\n  {label:'Encryption', pct:100, color:'--green'},\n  {label:'Identity', pct:85, color:'--blue'},\n  {label:'Networking', pct:100, color:'--green'},\n  {label:'Storage', pct:90, color:'--orange'},\n];\n\nconst BUDGET_THRESHOLDS = [\n  {pct:50, label:'Email Alert', color:'--blue'},\n  {pct:80, label:'Warning Alert', color:'--orange'},\n  {pct:100, label:'Critical Alert', color:'--red'},\n];\n\nconst COST_SERVICES = [\n  {name:'Compute', amount:18500}, {name:'Storage', amount:9200}, {name:'Networking', amount:4100}, {name:'Database', amount:12300},\n];\nconst COST_COMPARTMENTS = [\n  {name:'Development', amount:8200}, {name:'Testing', amount:5100}, {name:'Production', amount:30800},\n];\nconst WASTED_RESOURCES = [\n  {id:'vm', label:'Unused VM (dev-test-03)', savings:3200},\n  {id:'vol', label:'Idle Block Volume (50GB, unattached)', savings:900},\n  {id:'lb', label:'Unused Load Balancer', savings:1400},\n  {id:'snap', label:'Old Snapshots (90+ days)', savings:600},\n  {id:'pip', label:'Idle Public IP', savings:250},\n];\n\nconst TROUBLESHOOT = [\n  {id:'ts1', title:'Cloud Guard Not Detecting Threats', scenario:'A public bucket was created 2 hours ago but Cloud Guard shows no finding.', opts:['The Target scope doesn\\'t include that compartment','Cloud Guard only scans once per week','Buckets are never scanned by Cloud Guard','The bucket needs to be deleted and recreated'], a:0, ex:'If a compartment isn\\'t inside the configured Target, nothing in it gets monitored at all \u2014 regardless of how risky it is.'},\n  {id:'ts2', title:'Security Zone Blocks Deployment', scenario:'A developer can\\'t deploy a Compute instance with a public IP in the Production Security Zone.', opts:['This is expected \u2014 the zone\\'s \"No Public IPs\" policy is working as designed','The developer\\'s account is broken','The compartment quota is full','The shape doesn\\'t support public IPs'], a:0, ex:'Security Zones are meant to make non-compliant deployments impossible, not just warn about them.'},\n  {id:'ts3', title:'Budget Alerts Not Received', scenario:'Spend crossed 80% last week but no warning email arrived.', opts:['The alert rule\\'s notification/email subscription isn\\'t configured or confirmed','Budgets only alert at 100%','The budget was deleted automatically','Email alerts require a paid support plan'], a:0, ex:'A budget alert rule needs a working ONS (Notifications) topic subscription \u2014 an unconfirmed subscription silently drops alerts.'},\n  {id:'ts4', title:'Detector Recipe Disabled Accidentally', scenario:'The \"Open Security Lists\" detector rule shows as disabled, and a genuinely open port wasn\\'t flagged.', opts:['Re-enable the specific detector rule inside the Detector Recipe','Recreate the entire Cloud Guard configuration from scratch','Disable Cloud Guard and re-enable it','Nothing can be done \u2014 wait for the next release'], a:0, ex:'Individual rules inside a Detector Recipe can be toggled off \u2014 check the recipe\\'s rule list before assuming a bigger failure.'},\n  {id:'ts5', title:'Responder Not Executing', scenario:'A Responder Recipe rule is enabled but the automatic action never runs.', opts:['The Cloud Guard service account lacks the IAM policy to perform that action','Responders only work manually, never automatically','The rule needs to be deleted and recreated daily','Responders require a support ticket to activate'], a:0, ex:'Automated responder actions still need IAM policy allowing the Cloud Guard service to act on the target resources.'},\n];\n\nconst EXAM_CHALLENGES = [\n  {id:'e1', q:'A developer creates a public bucket inside Production. Which OCI Governance service blocks this automatically?', opts:['Security Zones','Cloud Guard (detection only)','Budgets','Cost Analysis'], a:0, ex:'Security Zones enforce policy at creation time and prevent the action; Cloud Guard would only detect it after the fact.'},\n  {id:'e2', q:'Cloud Guard detected an exposed database. Which component performs automatic remediation?', opts:['A Responder Recipe','A Detector Recipe','A Security Zone','A Budget'], a:0, ex:'Detector Recipes find problems; Responder Recipes are what actually take (or suggest) corrective action.'},\n  {id:'e3', q:'At which budget threshold should organizations typically receive an early warning?', opts:['50%','100%','Only at 100%','Budgets don\\'t support thresholds'], a:0, ex:'A 50% threshold gives an early heads-up long before spend becomes critical, alongside later 80%/100% escalations.'},\n  {id:'e4', q:'What is the relationship between a Target and a Detector/Responder Recipe?', opts:['A Target defines which compartments the recipes actually apply to','A Target replaces the need for recipes','A Target is only used for Budgets','A Target is a type of Security Zone'], a:0, ex:'Recipes define the rules; the Target defines the scope those rules are enforced against.'},\n  {id:'e5', q:'Why might an Autonomous Database with a public endpoint be flagged by Cloud Guard?', opts:['It bypasses network-layer access controls, exposing it directly to the internet','Public endpoints are always free','Cloud Guard flags all databases regardless of configuration','It has nothing to do with security'], a:0, ex:'A public endpoint means anyone on the internet can attempt to reach the database directly, skipping VCN-level protections.'},\n];\n\nconst ACHIEVEMENTS = [\n  {id:'a1', name:'Cloud Guardian', ico:'\ud83d\udee1', cond:'Enable Cloud Guard and configure its Target', check:s=>s.done.has('m1') && s.done.has('m2')},\n  {id:'a2', name:'Security Architect', ico:'\ud83c\udfdb', cond:'Configure Detector &amp; Responder Recipes', check:s=>s.done.has('m3') && s.done.has('m4')},\n  {id:'a3', name:'Compliance Champion', ico:'\ud83d\udccb', cond:'Deploy a Security Zone', check:s=>s.done.has('m5')},\n  {id:'a4', name:'Cost Optimizer', ico:'\ud83d\udcb0', cond:'Complete Budgets &amp; Cost Analysis', check:s=>s.done.has('m6') && s.done.has('m7')},\n  {id:'a5', name:'Threat Hunter', ico:'\ud83c\udfaf', cond:'Solve every troubleshooting scenario', check:s=>Object.keys(s.tsSolved).length>=TROUBLESHOOT.length},\n];\n\nconst QUIZZES = {\n  m1:[\n    {q:'What happens if Cloud Guard is disabled in a tenancy?', opts:['Misconfigurations and threats stop being automatically detected','Nothing \u2014 all security still works the same','Budgets automatically shut down','IAM policies are deleted'], a:0, ex:'Cloud Guard is the detection layer \u2014 without it, risky configurations can sit unnoticed indefinitely.'},\n    {q:'Which three components make up Cloud Guard\\'s architecture?', opts:['Detector, Responder, Target','Compartment, Policy, Group','VCN, Subnet, Gateway','Budget, Alert, Threshold'], a:0, ex:'Detectors find problems, Responders act on them, and the Target defines where the rules apply.'},\n  ],\n  m2:[\n    {q:'If only the Development compartment is set as the Target, what happens to Production?', opts:['Production remains completely unmonitored by Cloud Guard','Production is monitored automatically anyway','Production gets extra protection','Nothing changes for either compartment'], a:0, ex:'Cloud Guard only watches what\\'s inside its configured Target \u2014 anything outside that scope is invisible to it.'},\n    {q:'What is the broadest possible Cloud Guard Target?', opts:['The root tenancy','A single compute instance','A single user','A single VCN'], a:0, ex:'Targeting the root tenancy monitors every compartment beneath it, current and future.'},\n  ],\n  m3:[\n    {q:'What does a Detector Recipe actually contain?', opts:['A set of rules that identify risky configurations','A list of employees','A billing report','A network diagram'], a:0, ex:'Each rule in a Detector Recipe checks for a specific type of misconfiguration or suspicious pattern.'},\n    {q:'Which finding severity should be treated as most urgent?', opts:['Critical','Low','Medium','Informational'], a:0, ex:'Critical findings (e.g. a database or security list wide open) represent the most immediate exploitable risk.'},\n  ],\n  m4:[\n    {q:'In Cloud Guard\\'s response flow, what comes right after \"Threat Detected\"?', opts:['Cloud Guard evaluates it against Responder Rules','The tenancy is immediately suspended','A budget alert fires','The resource is deleted automatically'], a:0, ex:'Detection feeds into Cloud Guard, which then checks whether a matching Responder Rule should act.'},\n    {q:'What is the appropriate automatic response to an unused IAM user, per this lab?', opts:['Disable the user','Delete the tenancy','Make it an administrator','Ignore it'], a:0, ex:'Disabling (not necessarily deleting) an unused account reduces attack surface while preserving an audit trail.'},\n  ],\n  m5:[\n    {q:'What is the main difference between a Security Zone and Cloud Guard?', opts:['Security Zones prevent non-compliant actions; Cloud Guard detects them after the fact','They are the exact same service','Security Zones only work for budgets','Cloud Guard is a paid add-on and Security Zones are free'], a:0, ex:'Security Zones enforce policy proactively at creation time; Cloud Guard\\'s detectors flag issues after they exist.'},\n    {q:'Which of these would a Security Zone with \"Mandatory Encryption\" block?', opts:['A volume created without encryption','A volume created with encryption','A compartment rename','A budget update'], a:0, ex:'The zone rejects the creation outright if encryption isn\\'t applied \u2014 it doesn\\'t just warn.'},\n  ],\n  m6:[\n    {q:'What are the four typical fields when creating a Budget?', opts:['Name, Monthly Amount, Compartment, Description','Username, Password, Region, Shape','VCN, Subnet, CIDR, Gateway','Detector, Responder, Target, Recipe'], a:0, ex:'A Budget needs a name, a monetary cap, the compartment(s) it tracks, and an optional description.'},\n    {q:'Why configure multiple alert thresholds (50/80/100%)?', opts:['To give progressively urgent early warnings before spend becomes critical','Because OCI requires exactly three thresholds','To automatically stop all spending at 50%','Thresholds are only cosmetic'], a:0, ex:'Layered thresholds let teams react early instead of being surprised only when the budget is already exceeded.'},\n  ],\n  m7:[\n    {q:'Which view helps you see spend broken down by Compute, Storage, Networking, etc.?', opts:['Service breakdown in Cost Analysis','IAM policy list','Security Zone dashboard','Detector Recipe list'], a:0, ex:'Cost Analysis\\'s service breakdown shows exactly where tenancy spend is concentrated.'},\n    {q:'Which of these is a classic source of wasted cloud spend?', opts:['An idle, unattached block volume still being billed','A right-sized, actively used Compute instance','A budget with alert thresholds configured','A Security Zone with strict policies'], a:0, ex:'Unattached volumes, idle load balancers, and old snapshots quietly accumulate cost with zero business value.'},\n  ],\n};\n\n\n/* ================= STATE ================= */\nconst STATE = {\n  view:'home', xp:0, done:new Set(),\n  quizScores:{}, quizAnswered:{}, achUnlocked:new Set(),\n  m1:{enabled:false, attackShown:false, alertsShown:0},\n  m2:{targetScope:null},\n  m3:{detectors:{pubstorage:false, pubcompute:false, openseclist:false, weakiam:false, dbexposure:false}, selectedDetector:null, scanDone:false},\n  m4:{selectedAction:null, mapped:{}},\n  m5:{zoneEnabled:false, blocked:{}},\n  m6:{budget:null, created:false, spend:0, alerted:{}},\n  m7:{deleted:{}, filter:null},\n  tsSolved:{},\n  examSolved:{},\n  selectedChip:null,\n};\n\nfunction isUnlocked(id){\n  const idx = MISSION_ORDER.indexOf(id);\n  if(idx<=0) return true;\n  return STATE.done.has(MISSION_ORDER[idx-1]);\n}\nfunction rankFor(xp){\n  if(xp>=1300) return 'OCI Security & Governance Expert';\n  if(xp>=850) return 'Senior Security Engineer';\n  if(xp>=500) return 'Security Engineer';\n  if(xp>=150) return 'Associate Security Engineer';\n  return 'New Hire';\n}\nfunction computeSecurityScore(){\n  let s = 20;\n  if(STATE.m1.enabled) s += 20;\n  if(STATE.m2.targetScope==='root') s += 15; else if(STATE.m2.targetScope) s += 5;\n  s += Object.values(STATE.m3.detectors).filter(Boolean).length * 5;\n  s += Object.keys(STATE.m4.mapped).length * 5;\n  if(STATE.m5.zoneEnabled) s += 10;\n  if(STATE.m6.created) s += 3;\n  if(Object.keys(STATE.m7.deleted).length>=3) s += 2;\n  return Math.min(100, s);\n}\nfunction threatLevelFor(score){\n  if(score<40) return 'Critical';\n  if(score<60) return 'High';\n  if(score<80) return 'Medium';\n  return 'Low';\n}\nfunction complianceScore(){\n  if(STATE.m5.zoneEnabled) return 100;\n  const base = Math.round(COMPLIANCE_AREAS.reduce((a,c)=>a+c.pct,0)/COMPLIANCE_AREAS.length);\n  return base;\n}\nfunction monthlyCost(){\n  const total = COST_SERVICES.reduce((a,c)=>a+c.amount,0);\n  const saved = Object.keys(STATE.m7.deleted).reduce((a,id)=>a+(WASTED_RESOURCES.find(w=>w.id===id)?.savings||0),0);\n  return total - saved;\n}\n\nfunction addXP(n, label){\n  STATE.xp = Math.max(0, STATE.xp + n);\n  document.getElementById('xpDisplay').textContent = STATE.xp;\n  document.getElementById('rankChip').textContent = rankFor(STATE.xp);\n  toast(n>=0?'xp':'err', (n>=0?'+':'')+n+' XP', label||'');\n  checkAchievements();\n}\nfunction toast(type, title, msg){\n  const wrap = document.getElementById('toast-wrap');\n  const el = document.createElement('div');\n  el.className = 'toast ' + type;\n  const ico = type==='xp' ? '\u2b50' : type==='ok' ? '\u2705' : type==='err' ? '\u26d4' : '\u2139';\n  el.innerHTML = `<div class=\"t-ico\">${ico}</div><div><b>${title}</b><span>${msg||''}</span></div>`;\n  wrap.appendChild(el);\n  setTimeout(()=>{ el.style.transition='opacity .4s'; el.style.opacity='0'; setTimeout(()=>el.remove(),400); }, 3200);\n}\nfunction completeMission(id, xp){\n  if(STATE.done.has(id)) return;\n  STATE.done.add(id);\n  addXP(xp, MISSIONS.find(m=>m.id===id).title + ' complete');\n  toast('ok','Mission Complete', MISSIONS.find(m=>m.id===id).title);\n  renderSidebar();\n  const idx = MISSION_ORDER.indexOf(id);\n  if(idx>=0 && idx<MISSION_ORDER.length-1){\n    setTimeout(()=>toast('info','Next mission unlocked', MISSIONS[idx+1].title), 900);\n  }\n}\nfunction checkAchievements(){\n  ACHIEVEMENTS.forEach(a=>{\n    if(!STATE.achUnlocked.has(a.id) && a.check(STATE)){\n      STATE.achUnlocked.add(a.id);\n      setTimeout(()=>toast('ok','Achievement Unlocked \ud83c\udfc6', a.name), 600);\n    }\n  });\n}\n\n/* ================= NAV ================= */\nfunction renderSidebar(){\n  const groups = {main:'Overview', missions:'Mission Track', extra:'Beyond the Labs'};\n  let html = '';\n  Object.keys(groups).forEach(g=>{\n    html += `<h4>${groups[g]}</h4>`;\n    NAV.filter(n=>n.group===g).forEach(n=>{\n      let locked=false, done=false;\n      if(MISSION_ORDER.includes(n.id)){ locked=!isUnlocked(n.id); done=STATE.done.has(n.id); }\n      html += `<div class=\"nav-item ${STATE.view===n.id?'active':''} ${locked?'locked':''} ${done?'done':''}\"\n        onclick=\"${locked?'':`setView('${n.id}')`}\">\n        <span class=\"n-ico\">${done?'\u2713':n.ico}</span>${n.label}\n        ${locked?'<span class=\"nav-badge\">\ud83d\udd12</span>':''}\n      </div>`;\n    });\n  });\n  const pct = Math.round((STATE.done.size/MISSION_ORDER.length)*100);\n  html += `<div class=\"progress-mini\"><div class=\"lbl\"><span>Mission Progress</span><span>${pct}%</span></div>\n    <div class=\"bar-track\"><div class=\"bar-fill\" style=\"width:${pct}%\"></div></div></div>`;\n  document.getElementById('sidebar').innerHTML = html;\n}\nfunction setView(id){\n  STATE.view = id;\n  const nav = NAV.find(n=>n.id===id);\n  document.getElementById('crumbCurrent').textContent = nav ? nav.label : id;\n  renderSidebar();\n  renderMain();\n  const mainEl = document.getElementById('main');\n  if(mainEl.scrollIntoView) mainEl.scrollIntoView({behavior:'smooth', block:'start'});\n}\nfunction renderMain(){\n  const map = {\n    home:renderHome, missionmap:renderMissionMap,\n    m1:renderM1, m2:renderM2, m3:renderM3, m4:renderM4, m5:renderM5, m6:renderM6, m7:renderM7,\n    troubleshoot:renderTroubleshoot, exam:renderExam, achievements:renderAchievements, capstone:renderCapstone,\n  };\n  const fn = map[STATE.view] || renderHome;\n  document.getElementById('main').innerHTML = `<div class=\"view active\">${fn()}</div>`;\n  afterRenderHooks[STATE.view] && afterRenderHooks[STATE.view]();\n}\nconst afterRenderHooks = {};\n\nfunction gauge(label, pct, colorVar){\n  return `<div class=\"gauge-wrap\"><div class=\"page-sub\" style=\"margin-bottom:2px;\">${label}</div>\n    <div class=\"gauge-track\"><div class=\"gauge-fill\" style=\"width:${pct}%; background:var(${colorVar});\"></div></div>\n    <b style=\"font-size:13px;\">${pct}%</b></div>`;\n}\n\n/* ================= HOME (SOC Dashboard) ================= */\nfunction renderHome(){\n  const score = computeSecurityScore();\n  const threat = threatLevelFor(score);\n  const compliance = complianceScore();\n  const pct = Math.round((STATE.done.size/MISSION_ORDER.length)*100);\n  const nextMission = MISSIONS[STATE.done.size];\n  return `\n  <div class=\"section-head\">\n    <div class=\"eyebrow\">OCI Operations Professional \u00b7 1Z0-1067-26 \u00b7 Day 2 Lab</div>\n    <h1 class=\"page-title\">Secure Your Oracle Cloud Environment</h1>\n    <p class=\"page-sub\">You've just joined ABC Enterprise as the new OCI Cloud Security Engineer. The CIO's mission: secure the entire tenancy before attackers exploit any vulnerability.</p>\n  </div>\n  <div class=\"grid grid-4\" style=\"margin-bottom:16px;\">\n    <div class=\"card\"><div class=\"pill pill-red\">Security Score</div><h2 style=\"margin-top:10px;font-size:24px;\">${score}%</h2></div>\n    <div class=\"card\"><div class=\"pill ${threat==='Critical'||threat==='High'?'pill-red':threat==='Medium'?'pill-orange':'pill-green'}\">Threat Level</div><h2 style=\"margin-top:10px;font-size:20px;\">${threat}</h2></div>\n    <div class=\"card\"><div class=\"pill pill-blue\">Compliance</div><h2 style=\"margin-top:10px;font-size:24px;\">${compliance}%</h2></div>\n    <div class=\"card\"><div class=\"pill pill-orange\">XP</div><h2 style=\"margin-top:10px;font-size:24px;\">${STATE.xp}</h2></div>\n  </div>\n  <div class=\"grid grid-4\" style=\"margin-bottom:16px;\">\n    <div class=\"card\"><div class=\"pill pill-gray\">Cloud Guard Alerts</div><h3 style=\"margin-top:8px;\">${STATE.m1.attackShown ? ATTACK_ALERTS.length : 0}</h3></div>\n    <div class=\"card\"><div class=\"pill pill-gray\">Security Zone Violations Blocked</div><h3 style=\"margin-top:8px;\">${Object.keys(STATE.m5.blocked).length}</h3></div>\n    <div class=\"card\"><div class=\"pill pill-gray\">Current Budget</div><h3 style=\"margin-top:8px; font-size:14px;\">${STATE.m6.created ? '\u20b9'+STATE.m6.budget.amount : 'Not set'}</h3></div>\n    <div class=\"card\"><div class=\"pill pill-gray\">Monthly Cost</div><h3 style=\"margin-top:8px;\">\u20b9${monthlyCost().toLocaleString()}</h3></div>\n  </div>\n  <div class=\"card\" style=\"text-align:center; padding:40px 24px; background:linear-gradient(180deg, var(--red-glow), var(--panel));\">\n    <div style=\"font-size:13px; color:var(--text-dim); letter-spacing:1px; text-transform:uppercase; margin-bottom:10px;\">Current Mission</div>\n    <h2 style=\"font-size:21px; margin-bottom:10px;\">${nextMission ? 'Mission '+nextMission.num+' \u2014 '+nextMission.title : 'All Missions Complete!'}</h2>\n    <p class=\"page-sub\" style=\"margin:0 auto 20px;\">Mission progress: ${pct}%</p>\n    <button class=\"btn btn-primary\" onclick=\"setView('missionmap')\">\ud83d\ude80 Start Mission</button>\n  </div>`;\n}\n\n/* ================= MISSION MAP ================= */\nfunction renderMissionMap(){\n  let nodes = MISSIONS.map(m=>{\n    const locked = !isUnlocked(m.id); const done = STATE.done.has(m.id); const current = !locked && !done;\n    return `<div class=\"m-node ${locked?'locked':''} ${done?'done':''} ${current?'current':''}\" onclick=\"${locked?'':`setView('${m.id}')`}\">\n      <div class=\"m-num\">${done?'\u2713':m.num}</div><h4>${m.title}</h4><p>${m.desc}</p>\n      <div class=\"m-xp\">\u2b50 ${m.xp} XP</div>${locked?'<div class=\"pill pill-gray\" style=\"margin-top:6px;\">\ud83d\udd12 Locked</div>':''}\n    </div>`;\n  }).join('');\n  return `<div class=\"section-head\"><div class=\"eyebrow\">Security Operations Center</div><h1 class=\"page-title\">Mission Map</h1>\n  <p class=\"page-sub\">Secure the tenancy one mission at a time \u2014 each unlocks the next.</p></div>\n  <div class=\"mission-map\"><div class=\"mission-track\">${nodes}</div></div>`;\n}\n\n/* ================= M1: ENABLE CLOUD GUARD ================= */\nfunction renderM1(){\n  const done = STATE.done.has('m1');\n  const score = computeSecurityScore();\n  return `\n  <div class=\"section-head\"><div class=\"eyebrow\">Mission 1 \u00b7 100 XP</div><h1 class=\"page-title\">Enable Cloud Guard</h1>\n  <p class=\"page-sub\">Your tenancy starts insecure. Turn on OCI's threat detection engine.</p></div>\n  <div class=\"card\" style=\"margin-bottom:16px;\">\n    <div class=\"tag-list\" style=\"margin-bottom:10px;\"><span class=\"pill pill-red\">Security Score: ${score}%</span>${STATE.m1.enabled?'<span class=\"pill pill-green\">Cloud Guard: Active</span>':'<span class=\"pill pill-gray\">Cloud Guard: Disabled</span>'}</div>\n    ${!STATE.m1.enabled ? INSECURE_FINDINGS.map(f=>`<div class=\"finding-row\"><span class=\"sev-badge ${f.sev}\">${f.sev}</span>${f.label}</div>`).join('') : '<div class=\"info-box\">\u2713 Cloud Guard is now scanning the tenancy continuously.</div>'}\n    ${!STATE.m1.enabled ? `<button class=\"btn btn-primary\" style=\"margin-top:12px;\" onclick=\"enableCloudGuard()\">\ud83d\udee1 Enable Cloud Guard</button>` : ''}\n  </div>\n  <div class=\"grid grid-2\" style=\"margin-bottom:16px;\">\n    ${CLOUD_GUARD_CONCEPTS.map(c=>`<div class=\"card\" style=\"padding:14px;\"><b>${c.term}</b><p class=\"page-sub\" style=\"margin-top:6px;\">${c.def}</p></div>`).join('')}\n  </div>\n  ${STATE.m1.enabled ? `\n  <div class=\"hr\"></div>\n  <h4 style=\"margin-bottom:10px;\">Real Attack Simulation</h4>\n  ${!STATE.m1.attackShown ? `<button class=\"btn btn-ghost\" onclick=\"simulateAttack()\">\ud83d\udc64 Simulate Attacker Scanning the Cloud</button>` :\n    ATTACK_ALERTS.map(a=>`<div class=\"threat-card ${a.sev}\"><div class=\"tag-list\" style=\"margin-bottom:6px;\"><span class=\"sev-badge ${a.sev}\">${a.sev}</span><b>${a.title}</b></div><p class=\"page-sub\">${a.desc}</p></div>`).join('')}\n  ` : ''}\n  ${STATE.m1.enabled && STATE.m1.attackShown && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m1',100); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m1') : ''}`;\n}\nfunction enableCloudGuard(){\n  toast('info','Deploying Cloud Guard\u2026','Scanning tenancy for existing risks');\n  setTimeout(()=>{\n    STATE.m1.enabled = true;\n    addXP(15,'Cloud Guard active \u2014 Security Score rising');\n    renderMain();\n  }, 900);\n}\nfunction simulateAttack(){\n  STATE.m1.attackShown = true;\n  addXP(10,'Attack detected and logged');\n  renderMain();\n}\n\n/* ================= M2: CLOUD GUARD TARGET ================= */\nfunction renderM2(){\n  const done = STATE.done.has('m2');\n  const scope = STATE.m2.targetScope;\n  return `\n  <div class=\"section-head\"><div class=\"eyebrow\">Mission 2 \u00b7 90 XP</div><h1 class=\"page-title\">Create Cloud Guard Target</h1>\n  <p class=\"page-sub\">Choose what Cloud Guard actually watches. Click Root for full coverage, or a single compartment to see the tradeoff.</p></div>\n  <div class=\"hier-tree\">\n    ${HIERARCHY.map(h=>{\n      let cls = h.level===1?'child':'';\n      if(scope==='root') cls += ' covered';\n      else if(scope===h.id) cls += ' covered selected';\n      else if(scope && h.level===1) cls += ' exposed';\n      return `<div class=\"hier-node ${cls}\" onclick=\"selectTarget('${h.id}')\">${h.label} ${scope==='root'||scope===h.id?'\u2713 Monitored':(scope&&h.level===1?'\u26a0 Unmonitored':'')}</div>`;\n    }).join('')}\n  </div>\n  <div class=\"info-box\" style=\"margin-top:14px;\">\ud83d\udca1 Selecting Root Tenancy monitors every current and future compartment. Selecting a single compartment leaves the others completely blind to Cloud Guard.</div>\n  ${scope && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m2',90); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m2') : ''}`;\n}\nfunction selectTarget(id){\n  STATE.m2.targetScope = id;\n  addXP(10, id==='root' ? 'Root Tenancy targeted \u2014 full coverage' : id+' targeted \u2014 partial coverage');\n  renderMain();\n}\n\n/* ================= M3: DETECTOR RECIPES ================= */\nfunction renderM3(){\n  const done = STATE.done.has('m3');\n  const enabledCount = Object.values(STATE.m3.detectors).filter(Boolean).length;\n  const sel = STATE.m3.selectedDetector ? DETECTORS.find(d=>d.id===STATE.m3.selectedDetector) : null;\n  return `\n  <div class=\"section-head\"><div class=\"eyebrow\">Mission 3 \u00b7 110 XP</div><h1 class=\"page-title\">Configure Detector Recipes</h1>\n  <p class=\"page-sub\">Enable each rule, then click it to learn the risk, severity, and exam notes.</p></div>\n  ${DETECTORS.map(d=>`\n    <div class=\"detector-row\">\n      <div class=\"toggle ${STATE.m3.detectors[d.id]?'on':''}\" onclick=\"toggleDetector('${d.id}')\"><div class=\"knob\"></div></div>\n      <span style=\"flex:1; cursor:pointer;\" onclick=\"selectDetector('${d.id}')\"><b>${d.label}</b></span>\n      <span class=\"sev-badge ${d.severity.toLowerCase()}\">${d.severity}</span>\n    </div>`).join('')}\n  <div class=\"card\" style=\"margin-top:10px;\">${sel ? `<h4 style=\"margin-bottom:8px;\">${sel.label}</h4>\n    <p class=\"page-sub\" style=\"margin-bottom:8px;\"><b>Risk:</b> ${sel.risk}</p>\n    <p class=\"page-sub\" style=\"margin-bottom:8px;\"><b>Real example:</b> ${sel.example}</p>\n    <div class=\"tip-box\">\ud83c\udf93 ${sel.examtip}</div>\n    <div class=\"mistake-box\">\u26a0 Common mistake: ${sel.mistake}</div>` : 'Click a detector name above to see details.'}</div>\n  <div class=\"hr\"></div>\n  <h4 style=\"margin-bottom:10px;\">Live Security Scan</h4>\n  ${!STATE.m3.scanDone ? `<button class=\"btn btn-ghost\" ${enabledCount<3?'disabled':''} onclick=\"runScan()\">\ud83d\udd0d Scan Entire Tenancy</button>${enabledCount<3?'<p class=\"page-sub\" style=\"margin-top:6px;\">Enable at least 3 detectors first.</p>':''}` :\n    SCAN_FINDINGS.map(f=>`<div class=\"finding-row\"><span class=\"sev-badge ${f.sev}\">${f.sev}</span>${f.label}</div>`).join('')}\n  ${enabledCount>=DETECTORS.length && STATE.m3.scanDone && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m3',110); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m3') : ''}`;\n}\nfunction toggleDetector(id){\n  STATE.m3.detectors[id] = !STATE.m3.detectors[id];\n  addXP(STATE.m3.detectors[id]?6:-2, id+' detector '+(STATE.m3.detectors[id]?'enabled':'disabled'));\n  renderMain();\n}\nfunction selectDetector(id){\n  STATE.m3.selectedDetector = id;\n  renderMain();\n}\nfunction runScan(){\n  STATE.m3.scanDone = true;\n  toast('info','Scan complete','4 findings across the tenancy');\n  addXP(15,'Tenancy scan complete');\n  renderMain();\n}\n\n/* ================= M4: RESPONDER RECIPES ================= */\nfunction renderM4(){\n  const done = STATE.done.has('m4');\n  return `\n  <div class=\"section-head\"><div class=\"eyebrow\">Mission 4 \u00b7 120 XP</div><h1 class=\"page-title\">Configure Responder Recipes</h1>\n  <p class=\"page-sub\">Select an action, then click the threat it should remediate. Wrong pairings won't stick.</p></div>\n  <div class=\"card\" style=\"margin-bottom:14px;\">\n    <div class=\"arch-diagram\" style=\"display:flex; align-items:center; justify-content:center; gap:14px; flex-wrap:wrap;\">\n      <span class=\"pill pill-red\">Threat Detected</span><span>\u2192</span><span class=\"pill pill-blue\">Cloud Guard</span><span>\u2192</span><span class=\"pill pill-orange\">Responder Rule</span><span>\u2192</span><span class=\"pill pill-green\">Automatic Action</span>\n    </div>\n  </div>\n  <div class=\"two-col\">\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:10px;\">Responder Actions</h4>\n      <div class=\"chip-row\">${RESPONDER_ACTIONS.map(a=>`<button class=\"chip ${STATE.m4.selectedAction===a.id?'active':''}\" onclick=\"selectResponderAction('${a.id}')\">${a.label}</button>`).join('')}</div>\n    </div>\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:10px;\">Threats</h4>\n      ${RESPONDER_THREATS.map(t=>{\n        const mapped = STATE.m4.mapped[t.id];\n        return `<div class=\"finding-row\" style=\"cursor:pointer;\" onclick=\"mapResponder('${t.id}')\">\n          <span>${t.label}</span><span style=\"margin-left:auto;\">${mapped ? '<span class=\"pill pill-green\">'+RESPONDER_ACTIONS.find(a=>a.id===mapped).label+'</span>' : '<span class=\"pill pill-gray\">unmapped</span>'}</span>\n        </div>`;\n      }).join('')}\n    </div>\n  </div>\n  ${Object.keys(STATE.m4.mapped).length>=RESPONDER_THREATS.length && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m4',120); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m4') : ''}`;\n}\nfunction selectResponderAction(id){\n  STATE.m4.selectedAction = id;\n  renderMain();\n}\nfunction mapResponder(threatId){\n  if(STATE.m4.mapped[threatId]) return;\n  if(!STATE.m4.selectedAction){ toast('err','Select an action first',''); return; }\n  const t = RESPONDER_THREATS.find(x=>x.id===threatId);\n  if(t.correctAction===STATE.m4.selectedAction){\n    STATE.m4.mapped[threatId] = STATE.m4.selectedAction;\n    toast('ok','Correct mapping', t.label);\n    addXP(12,'Responder configured: '+t.label);\n    STATE.m4.selectedAction = null;\n    renderMain();\n  } else {\n    toast('err','Wrong action','That won\\'t fix '+t.label+'. Try again.');\n  }\n}\n\n/* ================= M5: SECURITY ZONES ================= */\nfunction renderM5(){\n  const done = STATE.done.has('m5');\n  const blockedCount = Object.keys(STATE.m5.blocked).length;\n  return `\n  <div class=\"section-head\"><div class=\"eyebrow\">Mission 5 \u00b7 120 XP</div><h1 class=\"page-title\">Deploy Security Zone</h1>\n  <p class=\"page-sub\">Make insecure deployments impossible in Production.</p></div>\n  ${!STATE.m5.zoneEnabled ? `\n  <div class=\"card\">\n    <h4 style=\"margin-bottom:10px;\">Security Zone Wizard</h4>\n    <div class=\"field\"><label>Compartment</label><select id=\"zoneCompartment\"><option>Production</option></select></div>\n    <button class=\"btn btn-primary\" onclick=\"enableZone()\">Enable Security Zone</button>\n  </div>` : `\n  <div class=\"card\" style=\"margin-bottom:16px;\">\n    <h4 style=\"margin-bottom:10px;\">Active Policies \u2014 Production</h4>\n    <div class=\"tag-list\">${SECURITY_ZONE_RULES.map(r=>`<span class=\"pill pill-red\">\ud83d\udd12 ${r}</span>`).join('')}</div>\n  </div>\n  <h4 style=\"margin-bottom:10px;\">Blocked Deployment Simulation (${blockedCount}/${BLOCKED_ATTEMPTS.length})</h4>\n  ${BLOCKED_ATTEMPTS.map(b=>`\n    <div class=\"card\" style=\"margin-bottom:10px; padding:14px;\">\n      <div style=\"display:flex; justify-content:space-between; align-items:center;\">\n        <b>${b.label}</b>${STATE.m5.blocked[b.id]?'<span class=\"pill pill-red\">\u2717 Blocked</span>':`<button class=\"btn btn-ghost btn-sm\" onclick=\"attemptDeploy('${b.id}')\">Attempt Deployment</button>`}\n      </div>\n      ${STATE.m5.blocked[b.id] ? `<p class=\"page-sub\" style=\"margin-top:8px;\">${b.reason}</p>` : ''}\n    </div>`).join('')}\n  <div class=\"hr\"></div>\n  <h4 style=\"margin-bottom:10px;\">Security Compliance Dashboard</h4>\n  <div class=\"grid grid-4\">${COMPLIANCE_AREAS.map(c=>gauge(c.label, c.pct, c.color)).join('')}</div>\n  `}\n  ${STATE.m5.zoneEnabled && blockedCount>=BLOCKED_ATTEMPTS.length && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m5',120); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m5') : ''}`;\n}\nfunction enableZone(){\n  STATE.m5.zoneEnabled = true;\n  toast('ok','Security Zone enabled','Production is now policy-protected.');\n  addXP(20,'Security Zone deployed');\n  renderMain();\n}\nfunction attemptDeploy(id){\n  STATE.m5.blocked[id] = true;\n  const b = BLOCKED_ATTEMPTS.find(x=>x.id===id);\n  toast('err','Deployment Blocked', b.label);\n  addXP(8,'Blocked: '+b.label);\n  renderMain();\n}\n\n/* ================= M6: BUDGETS ================= */\nfunction renderM6(){\n  const done = STATE.done.has('m6');\n  return `\n  <div class=\"section-head\"><div class=\"eyebrow\">Mission 6 \u00b7 90 XP</div><h1 class=\"page-title\">Create Budgets</h1>\n  <p class=\"page-sub\">Company monthly budget: \u20b950,000. Set it up with alert thresholds.</p></div>\n  ${!STATE.m6.created ? `\n  <div class=\"card\">\n    <div class=\"field\"><label>Budget Name</label><input id=\"bgName\" placeholder=\"Monthly-Tenancy-Budget\"></div>\n    <div class=\"field\"><label>Monthly Amount (\u20b9)</label><input id=\"bgAmount\" value=\"50000\"></div>\n    <div class=\"field\"><label>Compartment</label><select id=\"bgComp\"><option>Root Tenancy</option><option>Production</option><option>Development</option></select></div>\n    <div class=\"field\"><label>Description</label><input id=\"bgDesc\" placeholder=\"Tracks total enterprise cloud spend\"></div>\n    <button class=\"btn btn-primary\" onclick=\"createBudget()\">Create Budget</button>\n  </div>` : `\n  <div class=\"card\">\n    <h4 style=\"margin-bottom:8px;\">${STATE.m6.budget.name}</h4>\n    <p class=\"page-sub\" style=\"margin-bottom:14px;\">\u20b9${STATE.m6.budget.amount} / month \u00b7 ${STATE.m6.budget.compartment}</p>\n    <div class=\"slider-wrap\">\n      <label class=\"page-sub\">Current Spend: ${STATE.m6.spend}% of budget</label>\n      <input type=\"range\" min=\"0\" max=\"120\" value=\"${STATE.m6.spend}\" oninput=\"updateSpend(this.value)\">\n    </div>\n    <div class=\"tag-list\">${BUDGET_THRESHOLDS.map(t=>`<span class=\"pill ${STATE.m6.alerted[t.pct]?'pill-red':'pill-gray'}\">${STATE.m6.alerted[t.pct]?'\ud83d\udd14':'\u25cb'} ${t.pct}% \u2014 ${t.label}</span>`).join('')}</div>\n    <div id=\"budgetNotif\"></div>\n  </div>`}\n  <div class=\"info-box\">\ud83d\udca1 Layered thresholds (50/80/100%) give progressively urgent warnings before spend becomes critical.</div>\n  ${STATE.m6.created && STATE.m6.alerted[100] && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m6',90); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m6') : ''}`;\n}\nfunction createBudget(){\n  const name = document.getElementById('bgName').value.trim() || 'Monthly-Tenancy-Budget';\n  const amount = document.getElementById('bgAmount').value.trim() || '50000';\n  const compartment = document.getElementById('bgComp').value;\n  const desc = document.getElementById('bgDesc').value.trim();\n  STATE.m6.budget = {name, amount, compartment, desc};\n  STATE.m6.created = true;\n  toast('ok','Budget created', name);\n  addXP(15,'Budget created');\n  renderMain();\n}\nfunction updateSpend(val){\n  STATE.m6.spend = parseInt(val,10);\n  BUDGET_THRESHOLDS.forEach(t=>{\n    if(STATE.m6.spend>=t.pct && !STATE.m6.alerted[t.pct]){\n      STATE.m6.alerted[t.pct] = true;\n      toast(t.pct>=100?'err':'info', t.label, `Spend crossed ${t.pct}%`);\n      addXP(5, t.label+' triggered');\n    }\n  });\n  renderMain();\n}\n\n/* ================= M7: COST ANALYSIS ================= */\nfunction renderM7(){\n  const done = STATE.done.has('m7');\n  const cost = monthlyCost();\n  const deletedCount = Object.keys(STATE.m7.deleted).length;\n  return `\n  <div class=\"section-head\"><div class=\"eyebrow\">Mission 7 \u00b7 110 XP</div><h1 class=\"page-title\">Cost Analysis</h1>\n  <p class=\"page-sub\">Current monthly cost: \u20b9${cost.toLocaleString()}. Filter, analyze, and cut waste.</p></div>\n  <div class=\"chip-row\">${['Development','Testing','Production'].map(c=>`<button class=\"chip ${STATE.m7.filter===c?'active':''}\" onclick=\"filterM7('${c}')\">${c}</button>`).join('')}${STATE.m7.filter?`<button class=\"chip\" onclick=\"filterM7(null)\">Clear filter</button>`:''}</div>\n  <div class=\"two-col\">\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:10px;\">Service Breakdown</h4>\n      ${COST_SERVICES.map(s=>`<div class=\"finding-row\"><span>${s.name}</span><span style=\"margin-left:auto;\">\u20b9${s.amount.toLocaleString()}</span></div>`).join('')}\n    </div>\n    <div class=\"card\">\n      <h4 style=\"margin-bottom:10px;\">Compartment Usage</h4>\n      ${COST_COMPARTMENTS.filter(c=>!STATE.m7.filter || c.name===STATE.m7.filter).map(c=>`<div class=\"finding-row\"><span>${c.name}</span><span style=\"margin-left:auto;\">\u20b9${c.amount.toLocaleString()}</span></div>`).join('')}\n    </div>\n  </div>\n  <div class=\"hr\"></div>\n  <h4 style=\"margin-bottom:10px;\">Cost Optimization Game (${deletedCount}/${WASTED_RESOURCES.length} cleaned up)</h4>\n  ${WASTED_RESOURCES.map(w=>`\n    <div class=\"finding-row\">\n      <span>${w.label}</span>\n      <span style=\"margin-left:auto; display:flex; align-items:center; gap:8px;\">\n        <span class=\"pill pill-orange\">saves \u20b9${w.savings}/mo</span>\n        ${STATE.m7.deleted[w.id] ? '<span class=\"pill pill-green\">Deleted</span>' : `<button class=\"btn btn-ghost btn-sm\" onclick=\"deleteWaste('${w.id}')\">Delete</button>`}\n      </span>\n    </div>`).join('')}\n  ${deletedCount>=WASTED_RESOURCES.length && !done ? `<div style=\"margin-top:16px;\"><button class=\"btn btn-primary\" onclick=\"completeMission('m7',110); renderMain();\">\u2713 Complete Mission</button></div>` : ''}\n  ${done ? renderQuizBlock('m7') : ''}`;\n}\nfunction filterM7(name){\n  STATE.m7.filter = name;\n  renderMain();\n}\nfunction deleteWaste(id){\n  if(STATE.m7.deleted[id]) return;\n  STATE.m7.deleted[id] = true;\n  const w = WASTED_RESOURCES.find(x=>x.id===id);\n  toast('ok','Resource deleted', `Saving \u20b9${w.savings}/mo`);\n  addXP(10, w.label+' removed');\n  renderMain();\n}\n\n/* ================= TROUBLESHOOTING ================= */\nfunction renderTroubleshoot(){\n  const solvedCount = Object.keys(STATE.tsSolved).length;\n  return `<div class=\"section-head\"><div class=\"eyebrow\">Troubleshooting Missions</div><h1 class=\"page-title\">Fix What's Broken</h1>\n  <p class=\"page-sub\">${solvedCount}/${TROUBLESHOOT.length} scenarios resolved.</p></div>\n  ${TROUBLESHOOT.map(t=>`\n    <div class=\"card\" style=\"margin-bottom:12px;\">\n      <h5 style=\"margin-bottom:6px;\">${t.title} ${STATE.tsSolved[t.id]?'<span class=\"pill pill-green\">Solved</span>':''}</h5>\n      <p class=\"page-sub\" style=\"margin-bottom:10px;\">${t.scenario}</p>\n      <div id=\"tswrap-${t.id}\">\n        ${t.opts.map((o,i)=>`<div class=\"q-opt\" onclick=\"answerTS('${t.id}',${i})\">${o}</div>`).join('')}\n        <div class=\"q-explain\" id=\"tsex-${t.id}\">${t.ex}</div>\n      </div>\n    </div>`).join('')}`;\n}\nfunction answerTS(id, idx){\n  const t = TROUBLESHOOT.find(x=>x.id===id);\n  const container = document.getElementById('tswrap-'+id);\n  const opts = container.querySelectorAll('.q-opt');\n  opts.forEach((o,i)=>{ o.onclick=null; if(i===t.a) o.classList.add('correct'); else if(i===idx) o.classList.add('incorrect'); });\n  document.getElementById('tsex-'+id).classList.add('show');\n  if(idx===t.a){ if(!STATE.tsSolved[id]){ STATE.tsSolved[id]=true; addXP(12, t.title+' resolved'); } }\n  else toast('err','Not quite','Check the explanation below.');\n  renderSidebar();\n}\n\n/* ================= EXAM CHALLENGES ================= */\nfunction renderExam(){\n  const solvedCount = Object.keys(STATE.examSolved).length;\n  return `<div class=\"section-head\"><div class=\"eyebrow\">Certification Mode</div><h1 class=\"page-title\">Exam Challenges</h1>\n  <p class=\"page-sub\">${solvedCount}/${EXAM_CHALLENGES.length} answered correctly.</p></div>\n  ${EXAM_CHALLENGES.map(e=>`\n    <div class=\"quiz-q\" style=\"margin-bottom:20px;\">\n      <div class=\"q-txt\">${e.q}</div>\n      <div id=\"examwrap-${e.id}\">\n        ${e.opts.map((o,i)=>`<div class=\"q-opt\" onclick=\"answerExam('${e.id}',${i})\">${o}</div>`).join('')}\n        <div class=\"q-explain\" id=\"examex-${e.id}\">${e.ex}</div>\n      </div>\n    </div>`).join('')}`;\n}\nfunction answerExam(id, idx){\n  const e = EXAM_CHALLENGES.find(x=>x.id===id);\n  const container = document.getElementById('examwrap-'+id);\n  const opts = container.querySelectorAll('.q-opt');\n  opts.forEach((o,i)=>{ o.onclick=null; if(i===e.a) o.classList.add('correct'); else if(i===idx) o.classList.add('incorrect'); });\n  document.getElementById('examex-'+id).classList.add('show');\n  if(idx===e.a){ if(!STATE.examSolved[id]){ STATE.examSolved[id]=true; addXP(10, 'Exam challenge correct'); } }\n  else toast('err','Not quite','Review the explanation.');\n}\n\n/* ================= ACHIEVEMENTS ================= */\nfunction renderAchievements(){\n  return `<div class=\"section-head\"><div class=\"eyebrow\">Achievements</div><h1 class=\"page-title\">Trophy Case</h1>\n  <p class=\"page-sub\">${STATE.achUnlocked.size}/${ACHIEVEMENTS.length} unlocked</p></div>\n  <div class=\"grid grid-4\">\n    ${ACHIEVEMENTS.map(a=>{ const u = STATE.achUnlocked.has(a.id);\n      return `<div class=\"ach-card ${u?'':'locked'}\"><div class=\"ico\">${a.ico}</div><h5>${a.name}</h5><p>${u?'Unlocked':a.cond}</p></div>`;\n    }).join('')}\n  </div>`;\n}\n\n/* ================= CAPSTONE ================= */\nfunction renderCapstone(){\n  const allDone = MISSION_ORDER.every(m=>STATE.done.has(m));\n  const score = computeSecurityScore();\n  const compliance = complianceScore();\n  const checklist = [\n    {label:'Enable Cloud Guard', ok:STATE.done.has('m1')},\n    {label:'Configure Target', ok:STATE.done.has('m2')},\n    {label:'Create Detector Recipe', ok:STATE.done.has('m3')},\n    {label:'Create Responder Recipe', ok:STATE.done.has('m4')},\n    {label:'Deploy Security Zone', ok:STATE.done.has('m5')},\n    {label:'Attempt insecure deployments', ok:Object.keys(STATE.m5.blocked).length>=BLOCKED_ATTEMPTS.length},\n    {label:'Configure Budget', ok:STATE.done.has('m6')},\n    {label:'Analyze Costs', ok:STATE.done.has('m7')},\n    {label:'Reduce Monthly Spend', ok:Object.keys(STATE.m7.deleted).length>=WASTED_RESOURCES.length},\n  ];\n  return `\n  <div class=\"section-head\"><div class=\"eyebrow\">Capstone Lab</div><h1 class=\"page-title\">Enterprise Cloud Secured</h1>\n  <p class=\"page-sub\">You inherited a completely insecure Oracle Cloud environment. Here's the full remediation checklist.</p></div>\n  <div class=\"card\">${checklist.map(c=>`<div style=\"display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--border-soft);\">\n    <span class=\"pill ${c.ok?'pill-green':'pill-gray'}\">${c.ok?'\u2713':'\u25cb'}</span><span>${c.label}</span></div>`).join('')}</div>\n  ${allDone ? `\n  <div class=\"card\" style=\"text-align:center; margin-top:18px; padding:44px; background:linear-gradient(180deg, rgba(61,220,132,.12), var(--panel));\">\n    <div style=\"font-size:44px;margin-bottom:10px;\">\ud83c\udf93</div>\n    <h2 style=\"margin-bottom:8px;\">Mission Complete \u2014 Enterprise Cloud Secured</h2>\n    <div class=\"grid grid-4\" style=\"margin:16px 0; text-align:left;\">\n      <div class=\"card\" style=\"padding:12px;\"><div class=\"pill pill-red\">Security Score</div><h3 style=\"margin-top:6px;\">${score}%</h3></div>\n      <div class=\"card\" style=\"padding:12px;\"><div class=\"pill pill-blue\">Compliance</div><h3 style=\"margin-top:6px;\">${compliance}%</h3></div>\n      <div class=\"card\" style=\"padding:12px;\"><div class=\"pill pill-green\">Budget</div><h3 style=\"margin-top:6px; font-size:14px;\">Healthy</h3></div>\n      <div class=\"card\" style=\"padding:12px;\"><div class=\"pill pill-orange\">Cloud Guard</div><h3 style=\"margin-top:6px; font-size:14px;\">Active</h3></div>\n    </div>\n    <p class=\"page-sub\" style=\"margin-bottom:14px;\">OCI Security &amp; Governance Expert \u00b7 XP ${STATE.xp}</p>\n    <div class=\"pill pill-green\" style=\"font-size:13px; padding:8px 16px;\">Certificate Ready</div>\n  </div>` : `<div class=\"tip-box\" style=\"margin-top:16px;\">Complete all 7 missions (and the bonus tasks above) to fully secure the tenancy.</div>`}`;\n}\n\n/* ================= QUIZ BLOCK (reused) ================= */\nfunction renderQuizBlock(missionId){\n  const qs = QUIZZES[missionId];\n  if(!qs) return '';\n  const answered = STATE.quizAnswered[missionId] || {};\n  return `<div class=\"card\" style=\"margin-top:20px;\"><h4 style=\"margin-bottom:14px;\">\ud83c\udfaf Knowledge Check</h4>\n    ${qs.map((q,qi)=>`<div class=\"quiz-q\"><div class=\"q-txt\">${qi+1}. ${q.q}</div>\n      ${q.opts.map((o,oi)=>`<div class=\"q-opt ${answered[qi]===oi?(oi===q.a?'correct':'incorrect'):''}\" onclick=\"answerQuiz('${missionId}',${qi},${oi})\">${o}</div>`).join('')}\n      <div class=\"q-explain ${answered[qi]!==undefined?'show':''}\">${q.ex}</div></div>`).join('')}\n  </div>`;\n}\nfunction answerQuiz(missionId, qi, oi){\n  if(!STATE.quizAnswered[missionId]) STATE.quizAnswered[missionId] = {};\n  if(STATE.quizAnswered[missionId][qi] !== undefined) return;\n  STATE.quizAnswered[missionId][qi] = oi;\n  const q = QUIZZES[missionId][qi];\n  if(oi===q.a){ STATE.quizScores[missionId] = (STATE.quizScores[missionId]||0)+1; addXP(10,'Correct answer'); }\n  else toast('err','Not quite','Review the explanation.');\n  renderMain();\n}\n\n/* ================= INIT ================= */\nfunction toggleTheme(){\n  const theme = document.body.getAttribute('data-theme')==='dark' ? 'light' : 'dark';\n  document.body.setAttribute('data-theme', theme);\n}\ndocument.getElementById('themeToggle').addEventListener('click', toggleTheme);\nrenderSidebar();\nrenderMain();\nwindow.STATE = STATE;\nObject.assign(window, {QUIZZES, MISSIONS, MISSION_ORDER, HIERARCHY, DETECTORS, SCAN_FINDINGS,\n  RESPONDER_THREATS, RESPONDER_ACTIONS, BLOCKED_ATTEMPTS, BUDGET_THRESHOLDS, WASTED_RESOURCES,\n  TROUBLESHOOT, EXAM_CHALLENGES, ACHIEVEMENTS, ATTACK_ALERTS});\n\n"};
